module benchmark/solution

type Result[a] = Ok(a) | Err(string)

pure func validate_age(age: int) -> Result[int] =
  if age >= 0 && age <= 150 then Ok(age) else Err("Age out of range")

pure func calculate_retirement_years(age: int) -> Result[int] =
  if age < 65 then Ok(65 - age) else Err("Already retired")

pure func retirement_result(age: int) -> Result[int] =
  match validate_age(age) {
    Ok(valid_age) => calculate_retirement_years(valid_age),
    Err(msg) => Err(msg)
  }

func print_result(result_value: Result[int]) -> () ! {IO} =
  match result_value {
    Ok(value) => println("Years to retirement: ${show(value)}"),
    Err(msg) => println("Error: ${msg}")
  }

export func main() -> () ! {IO} {
  print_result(retirement_result(30));
  print_result(retirement_result(70));
  print_result(retirement_result(-5))
}

